function lookup<T extends readonly [number,number,...unknown[]]>(ranges:readonly T[],c:string):T|undefined {
 const n=c.codePointAt(0);if(n===undefined)return undefined;
 let lo=0,hi=ranges.length-1;
 while(lo<=hi){const mid=(lo+hi)>>>1,r=ranges[mid];if(n<r[0])hi=mid-1;else if(n>r[1])lo=mid+1;else return r;}
 return undefined;
}
export function unicodeCategory(c:string):string{return lookup(CATEGORY_RANGES,c)?.[2]??'Cn';}
export function unicodeCombining(c:string):number{return lookup(COMBINING_RANGES,c)?.[2]??0;}
export function unicodeIsUpper(c:string):boolean{return lookup(UPPER_RANGES,c)!==undefined;}
export function unicodeIsLower(c:string):boolean{return lookup(LOWER_RANGES,c)!==undefined;}
export function unicodeAlphabetic(c:string):boolean{return lookup(ALPHABETIC_RANGES,c)!==undefined;}
export function unicodeMark(c:string):boolean{return lookup(MARK_RANGES,c)!==undefined;}
export function unicodeLower(c:string):string{return LOWER_MAP[c]??c;}
